const envelope = $input.first().json;
const payload = envelope.body ?? envelope;

if (payload.schemaVersion !== 1 || payload.source !== 'tender-radar') {
  throw new Error('حمولة غير معتمدة: يلزم schemaVersion=1 وsource=tender-radar');
}
if (!Array.isArray(payload.items)) {
  throw new Error('حمولة غير معتمدة: items يجب أن تكون مصفوفة');
}

const fields = ['title', 'agency', 'fee', 'region', 'deadline', 'publishedAt', 'platformStatus', 'activity', 'etimadUrl'];
const normalize = (item) => ({
  reference: String(item.reference ?? '').trim(),
  title: String(item.title ?? '').trim(),
  agency: String(item.agency ?? '').trim(),
  fee: Number.isFinite(Number(item.fee)) ? Number(item.fee) : 0,
  region: String(item.region ?? '').trim(),
  deadline: String(item.deadline ?? '').trim(),
  publishedAt: String(item.publishedAt ?? '').trim(),
  platformStatus: String(item.platformStatus ?? '').trim(),
  activity: String(item.activity ?? '').trim(),
  etimadUrl: String(item.etimadUrl ?? '').trim(),
});
const fingerprint = (item) => JSON.stringify(fields.map((field) => item[field]));
const changedFields = (previous, current) => fields.filter((field) => JSON.stringify(previous?.[field] ?? null) !== JSON.stringify(current[field] ?? null));

const unique = new Map();
for (const raw of payload.items) {
  const item = normalize(raw);
  if (item.reference) unique.set(item.reference, item);
}
const items = [...unique.values()];
const now = new Date().toISOString();

if (payload.dryRun === true) {
  return [{ json: {
    ok: true,
    dryRun: true,
    workflow: 'Radar Phase 1 · Local n8n',
    syncId: payload.syncId,
    duplicate: false,
    counts: { new: 0, changed: 0, unchanged: items.length },
    alert: { title: 'اختبار ناجح', message: 'اتصال n8n المحلي جاهز، ولم تُحفظ بيانات الاختبار.' },
    recordedAt: now,
  } }];
}

const store = $getWorkflowStaticData('global');
store.records = store.records ?? {};
store.history = Array.isArray(store.history) ? store.history : [];
store.processedSyncIds = Array.isArray(store.processedSyncIds) ? store.processedSyncIds : [];

if (store.processedSyncIds.includes(payload.syncId)) {
  return [{ json: {
    ok: true,
    workflow: 'Radar Phase 1 · Local n8n',
    syncId: payload.syncId,
    duplicate: true,
    counts: { new: 0, changed: 0, unchanged: items.length },
    alert: { title: 'تشغيل مكرر', message: 'تم تجاهل نتيجة المزامنة لأنها سُجلت سابقًا.' },
    recordedAt: now,
    historySize: store.history.length,
  } }];
}

const initialized = store.initialized === true;
const declaredAdded = new Set(Array.isArray(payload.declaredAdded) ? payload.declaredAdded.map(String) : []);
const declaredChanged = new Set(Array.isArray(payload.declaredChanged) ? payload.declaredChanged.map(String) : []);
const newItems = [];
const changedItems = [];
let unchanged = 0;

for (const current of items) {
  const previousRecord = store.records[current.reference];
  const currentFingerprint = fingerprint(current);
  let classification = 'unchanged';

  if (!initialized) {
    if (declaredAdded.has(current.reference)) classification = 'new';
    else if (declaredChanged.has(current.reference)) classification = 'changed';
  } else if (!previousRecord) classification = 'new';
  else if (previousRecord.fingerprint !== currentFingerprint) classification = 'changed';

  if (classification === 'new') {
    newItems.push(current);
  } else if (classification === 'changed') {
    changedItems.push({
      ...current,
      changedFields: previousRecord ? changedFields(previousRecord.snapshot, current) : ['تحديث معلن من الرادار'],
      previous: previousRecord?.snapshot ?? null,
    });
  } else {
    unchanged += 1;
  }

  store.records[current.reference] = {
    fingerprint: currentFingerprint,
    snapshot: current,
    firstSeenAt: previousRecord?.firstSeenAt ?? now,
    lastSeenAt: now,
  };
}

store.initialized = true;
store.processedSyncIds = [...store.processedSyncIds, payload.syncId].slice(-200);
const historyEntry = {
  syncId: payload.syncId,
  occurredAt: payload.occurredAt,
  recordedAt: now,
  counts: { new: newItems.length, changed: changedItems.length, unchanged },
  newReferences: newItems.map((item) => item.reference),
  changedReferences: changedItems.map((item) => item.reference),
};
store.history = [...store.history, historyEntry].slice(-500);

const totalChanges = newItems.length + changedItems.length;
const message = totalChanges
  ? `سجّل n8n ${newItems.length} منافسة جديدة و${changedItems.length} منافسة متغيرة.`
  : `لم تظهر منافسات جديدة أو متغيرة ضمن ${items.length} منافسة مستلمة.`;

return [{ json: {
  ok: true,
  workflow: 'Radar Phase 1 · Local n8n',
  syncId: payload.syncId,
  duplicate: false,
  counts: historyEntry.counts,
  alert: { title: totalChanges ? 'تحديثات جديدة في الرادار' : 'لا توجد تغييرات', message },
  newItems,
  changedItems,
  recordedAt: now,
  historySize: store.history.length,
} }];
